import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:4000/api'; /* process.env.REACT_APP_API_URL */

//||  

export interface Cliente {
  _id: string;
  nickname?: string;
  name?: string;
  lastname?: string;
  email?: string;
  codigoAcceso?: string;
  phone?: string;
  address?: string;
  cbu?: string;
  aliasCbu?: string;
  emailVerified?: boolean;
  phoneVerified?: boolean;
  role?: string;
  username?: string;
  hasPassword?: boolean;
}
export interface User {
  id: string;
  username: string;
  email: string;
  role: string;
  emailVerified?: boolean;
  phoneVerified?: boolean;
}

export interface AuthState {
  user: Cliente | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

const initialState: AuthState = {
  user: null,
  token: localStorage.getItem('authToken'),
  isAuthenticated: false,
  isLoading: false,
  error: null,
};

// Login con código de acceso
export const loginWithCode = createAsyncThunk(
  'auth/loginWithCode',
  async ({ codigoAcceso }: { codigoAcceso: string }, { rejectWithValue }) => {
    try {

      console.log("codigoAcceso",codigoAcceso);
      const response = await axios.post(`${API_BASE_URL}/auth/login`, { codigoAcceso });
      const { token, cliente } = response.data;
      
      localStorage.setItem('authToken', token);
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      
      return { token, cliente };
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.mensaje || 'Error de autenticación');
    }
  }
);

// Login con email/password
export const loginWithCredentials = createAsyncThunk(
  'auth/loginWithCredentials',
  async ({ username, password }: { username: string; password: string }, { rejectWithValue }) => {
    try {
      console.log("username",username);
      console.log("password",password);
      const response = await axios.post(`${API_BASE_URL}/auth/login`, { username, password });
      const { token, user } = response.data;
      console.log("response.data",response.data);
      localStorage.setItem('authToken', token);
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      
      return { token, cliente: user };
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.mensaje || 'Error de autenticación');
    }
  }
);

// Mantener compatibilidad con el login existente
export const login = createAsyncThunk(
  'auth/login',
  async ({ codigoAcceso }: { codigoAcceso: string }, { rejectWithValue }) => {
    try {
      const response = await axios.post(`${API_BASE_URL}/auth/login`, { codigoAcceso });
      const { token, cliente,user } = response.data;
      
      localStorage.setItem('authToken', token);
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      
      return { token, cliente:cliente||user };  
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.mensaje || 'Error de autenticación');
    }
  }
);

export const verifyToken = createAsyncThunk(
  'auth/verifyToken',
  async (_, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        return rejectWithValue('No hay token disponible');
      }

      const response = await axios.get(`${API_BASE_URL}/auth/verificar`, {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      return response.data.cliente;
    } catch (error: any) {
      return rejectWithValue('Token inválido');
    }
  }
);

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    logout: (state) => {
      localStorage.removeItem('authToken');
      delete axios.defaults.headers.common['Authorization'];
      state.user = null;
      state.token = null;
      state.isAuthenticated = false;
      state.error = null;
    },
    clearError: (state) => {
      state.error = null;
    },
    updateUserProfileInSlice: (state, action: PayloadAction<Cliente>) => {
      if (state.user && action.payload) {
        state.user = { ...state.user, ...action.payload };
      }
    },
  },
  extraReducers: (builder) => {
    builder
      // Login con código de acceso
      .addCase(loginWithCode.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(loginWithCode.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload.cliente;
        state.token = action.payload.token;
      })
      .addCase(loginWithCode.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })
      // Login con credenciales
      .addCase(loginWithCredentials.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(loginWithCredentials.fulfilled, (state, action) => {
        console.log("action.payload",action.payload);
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload.cliente;
        state.token = action.payload.token;
      })
      .addCase(loginWithCredentials.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })
      // Login (mantener compatibilidad)
      .addCase(login.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(login.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload.cliente;
        state.token = action.payload.token;
      })
      .addCase(login.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })
      // Verify Token
      .addCase(verifyToken.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(verifyToken.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
      })
      .addCase(verifyToken.rejected, (state) => {
        state.isLoading = false;
        state.isAuthenticated = false;
        state.user = null;
        state.token = null;
      });
  },
});

export const { logout, clearError, updateUserProfileInSlice } = authSlice.actions;
export default authSlice.reducer; 